use spore_core::{creature_skin_edge_commit_v1::commit,native_sse::Policy};use std::io::Write;
fn main(){let mut bytes=Vec::new();for initial in 0..2 {let mut records=[[0,u32::MAX,77,0,0,0]];let mut positions=[[0.;3];2];let mut counts=[[0;2];2];if initial==1{positions[0]=[8.,9.,10.];counts[0]=[4,5];}let mut slots=vec![[0;3];0x8000];let mut len=initial;let idx=commit(&mut records,0,9,&mut positions,&mut counts,&mut len,&mut slots,4,[3,4],[1.,2.,3.],Policy::Mxcsr1f80).unwrap();for v in [idx,records[0][1],records[0][2],len as u32,positions[initial][0].to_bits(),positions[initial][1].to_bits(),positions[initial][2].to_bits(),counts[initial][0],counts[initial][1],slots[4][0],slots[4][1],slots[4][2]]{bytes.extend_from_slice(&v.to_le_bytes());}}std::io::stdout().write_all(&bytes).unwrap();}
